<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/bootstrap.php';
use VCX\Parity\{Store,ControlTower,Auth,Structure,Importer};
use VCX\Core\Database;
Store::check(str_ends_with(getenv('DB_DATABASE')?:'','_test'),'Tests require isolated DB_DATABASE ending _test');
$db=Database::connect();$s=new Store($db);$app=new ControlTower($s);$passed=0;$failed=0;$assertions=0;
function ok(bool $condition,string $msg='assertion'): void {global$assertions;$assertions++;if(!$condition)throw new RuntimeException($msg);}
function eq(mixed $a,mixed $b,string $msg='equal'): void {ok($a===$b,$msg.' '.json_encode([$a,$b]));}
function denied(callable $fn,string $contains=''): void {try{$fn();}catch(RuntimeException $e){ok($contains===''||str_contains($e->getMessage(),$contains),'Expected denial '.$contains.', got '.$e->getMessage());return;}throw new RuntimeException('Expected rejection');}
function test(string $name,callable $fn): void {global$db,$s,$passed,$failed;$db->beginTransaction();$s->invalidate();try{$fn();$passed++;echo"PASS $name\n";}catch(Throwable $e){$failed++;echo"FAIL $name: ".$e->getMessage()."\n";}finally{if($db->inTransaction())$db->rollBack();$s->invalidate();}}
function token(string $id): string {global$s;$token=hash('sha256','synthetic-'.$id);$salt='synthetic-salt';$s->put('AUTH_USERS',['User_ID'=>$id,'Username'=>strtolower($id).'-user','Password_Salt'=>$salt,'Password_Hash'=>Auth::derive('test-only-passphrase',$salt,12000),'Iterations'=>'12000','Active'=>'TRUE','Must_Change_Password'=>'FALSE','Created_At'=>Store::now()]);$s->put('AUTH_SESSIONS',['Session_ID'=>'TEST-'.$id,'User_ID'=>$id,'Token_Hash'=>hash('sha256',$token),'Created_At'=>Store::now(),'Expires_At'=>'2099-01-01T00:00:00.000Z','Revoked'=>'FALSE']);return$token;}
function call(string $who,string $method,array $args=[]): mixed {global$app;return$app->call($method,$args,token($who));}
function write(string $who,string $method,array $args=[]): mixed {$args[]='UNIFIED_TASKS_V2';return call($who,$method,$args);}
const P='DEMO-PRJ-01';const T='DEMO-TSK-01-1-4';

test('unit: PBKDF2 matches GAS known HMAC-SHA256 derivation',function(){eq(Auth::derive('test-only-passphrase','synthetic-salt',12000),hash_pbkdf2('sha256','test-only-passphrase|'.getenv('AUTH_PEPPER'),'synthetic-salt',12000,64));});
test('unit: strict dates and inclusive calendar guards',function()use($app){ControlTower::date('2024-02-29',true);denied(fn()=>ControlTower::date('2026-02-29',true));eq(ControlTower::addDay('2026-12-31',1),'2027-01-01');eq($app->addWorking('2026-11-14',0),'2026-11-17');eq($app->addWorking('2026-11-20',1),'2026-11-21');});
test('unit: GAS Number coercion and procedure fallback retain source semantics',function(){eq(ControlTower::number('0x10'),16.0);eq(ControlTower::number('0b11'),3.0);eq(ControlTower::number('  '),0.0);eq(ControlTower::number('2.5'),2.5);ok(is_nan(ControlTower::number('2invalid')));ok(is_nan(ControlTower::number('2,5')));eq(ControlTower::duration('2invalid'),1.0);eq(ControlTower::duration(''),1.0);ok(ControlTower::numberRange('0x32',0,100));});
test('auth: login, active account, expiry, revoke, mandatory password change',function()use($app,$s){$t=token('ADMIN');$r=$app->call('login',['ADMIN-USER','test-only-passphrase']);ok(strlen($r['token'])===64);eq($app->auth->actor($r['token'])['User_ID'],'ADMIN');$session=ControlTower::filter($s->rows('AUTH_SESSIONS'),fn($row)=>$row['Token_Hash']===hash('sha256',$r['token']))[0];$session['Expires_At']='2000-01-01T00:00:00.000Z';$s->put('AUTH_SESSIONS',$session);denied(fn()=>$app->auth->actor($r['token']),'hết hạn');$session['Expires_At']=$r['expiresAt'];$s->put('AUTH_SESSIONS',$session);$app->call('logout',[],$r['token']);denied(fn()=>$app->auth->actor($r['token']),'hết hạn');$a=$s->find('AUTH_USERS','ADMIN');$a['Must_Change_Password']='TRUE';$s->put('AUTH_USERS',$a);denied(fn()=>$app->call('getProjects',[],$t),'mật khẩu tạm');ok($app->call('getBootstrap',[],$t)['needsPasswordChange']);$app->call('changePassword',['test-only-passphrase','changed-test-password'],$t);denied(fn()=>$app->auth->actor($t),'hết hạn');ok($app->call('login',['admin-user','changed-test-password'])['token']!=='');});
test('auth: five failed attempts commit before 15 minute lock',function()use($app,$s){token('ADMIN');for($i=0;$i<5;$i++)denied(fn()=>$app->call('login',['admin-user','invalid']),'không hợp lệ');eq(count($s->rows('LOGIN_ATTEMPTS')),5);denied(fn()=>$app->call('login',['admin-user','test-only-passphrase']),'15 phút');});
