test('permissions: all four roles, membership, assigned-only visibility and archived read rules',function()use($s){eq(count(call('ADMIN','getProjects')),10);eq(count(call('EXEC','getProjects')),10);eq(count(call('OTHER','getProjects')),0);denied(fn()=>call('OTHER','getProjectDetail',[P]),'quyền xem');$d=call('PIC','getProjectDetail',[P]);ok(!$d['canEdit']&&$d['isMember']&&in_array(T,$d['myTaskIds'],true));ok(call('PM','getProjectDetail',[P])['canEdit']);write('ADMIN','setProjectArchived',[P,true]);eq(count(call('EXEC','getProjects')),9);ok(!call('ADMIN','getProjectDetail',[P])['canEdit']);denied(fn()=>call('PIC','getProjectDetail',[P]),'quyền xem');write('ADMIN','setProjectArchived',[P,false]);eq($s->find('PROJECTS',P)['Status'],'On Hold');});
test('projects: admin creates, planner whitelist edits, dates/RAG/groups validated',function()use($s){denied(fn()=>write('PM','saveProject',[['Project_Name'=>'No','Status'=>'In Progress','RAG'=>'Green']]),'PMO_ADMIN');$r=write('ADMIN','saveProject',[['Project_Name'=>'Created','Status'=>'In Progress','RAG'=>'Green','PM_ID'=>'PM']]);$id=$r['id'];write('PM','saveProject',[['Project_ID'=>$id,'Project_Name'=>'Edited','Last_Updated'=>'injected']]);eq($s->find('PROJECTS',$id)['Project_Name'],'Edited');ok($s->find('PROJECTS',$id)['Last_Updated']!=='injected');denied(fn()=>write('PM','saveProject',[['Project_ID'=>$id,'RAG'=>'Purple']]),'RAG');denied(fn()=>write('PM','saveProject',[['Project_ID'=>$id,'Start_Date'=>'2026-11-20','End_Date'=>'2026-11-01']]),'trước');denied(fn()=>write('PM','saveProject',[['Project_ID'=>$id,'Group_ID'=>'absent']]),'Nhóm');});
