test('batch: partial outcomes, stable IDs, conflict detection, duplicate ops, tmp references',function()use($s){$op='aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa';$ops=[['opId'=>$op,'kind'=>'create','fields'=>['Task_Name'=>'Fast entry']],['opId'=>'bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb','kind'=>'create','fields'=>['Task_Name'=>'=formula']]];$r=write('PM','saveTaskBatch',[P,$ops]);ok(!$r['ok']&&$r['results'][0]['ok']&&!$r['results'][1]['ok']);$t=$r['results'][0];$retry=write('PM','saveTaskBatch',[P,[$ops[0]]]);eq($retry['results'][0]['id'],$t['id']);$update=['opId'=>'cccccccc-cccc-cccc-cccc-cccccccccccc','kind'=>'update','taskId'=>$t['id'],'baseVersion'=>'stale','fields'=>['Task_Name'=>'New']];$conflict=write('PM','saveTaskBatch',[P,[$update]]);eq($conflict['results'][0]['code'],'CONFLICT');$update['baseVersion']=$t['version'];ok(write('PM','saveTaskBatch',[P,[$update]])['ok']);$replay=write('PM','saveTaskBatch',[P,[$ops[0]]]);eq($replay['results'][0]['task']['Task_Name'],'New');$child=['opId'=>'dddddddd-dddd-dddd-dddd-dddddddddddd','kind'=>'create','fields'=>['Task_Name'=>'Child','Parent_Task_ID'=>'tmp-'.$op]];ok(write('PM','saveTaskBatch',[P,[$child]])['ok']);$dupe=write('PM','saveTaskBatch',[P,[$ops[0],$ops[0]]]);ok(!$dupe['results'][1]['ok']);});
test('batch: PIC cannot edit plan/system fields, executive cannot edit execution',function(){foreach(['Start_Date','PIC_ID','Project_ID','Member_Updated_At']as$field){$r=write('PIC','saveTaskBatch',[P,[['opId'=>'eeeeeeee-eeee-eeee-eeee-eeeeeeeeeeee','kind'=>'update','taskId'=>T,'fields'=>[$field=>'invalid']]]]);ok(!$r['results'][0]['ok']);}$d=call('PIC','getProjectDetail',[P]);$r=write('PIC','saveTaskBatch',[P,[['opId'=>'eeeeeeee-eeee-eeee-eeee-eeeeeeeeeeee','kind'=>'update','taskId'=>T,'baseVersion'=>((array)$d['taskVersions'])[T],'fields'=>['Progress'=>'80']]]]);ok($r['ok']);$d=call('EXEC','getProjectDetail',[P]);$r=write('EXEC','saveTaskBatch',[P,[['opId'=>'eeeeeeee-eeee-eeee-eeee-eeeeeeeeeeee','kind'=>'update','taskId'=>T,'baseVersion'=>((array)$d['taskVersions'])[T],'fields'=>['Progress'=>'90']]]]);ok(!$r['ok']);});
test('structure: indent/outdent/up/down, idempotent replay and stale structure CAS',function()use($s){$d=call('PM','getProjectDetail',[P]);$cmd=['opId'=>'ffffffff-ffff-ffff-ffff-ffffffffffff','action'=>'indent','taskIds'=>[T],'baseVersion'=>$d['structureVersion']];$r=write('PM','changeTaskStructure',[P,$cmd]);ok($r['ok'],json_encode($r));eq($s->find('TASKS',T)['Parent_Task_ID'],'DEMO-TSK-01-1-1');ok(write('PM','changeTaskStructure',[P,$cmd])['ok']);$stale=$cmd;$stale['opId']='gggggggg-gggg-gggg-gggg-gggggggggggg';eq(write('PM','changeTaskStructure',[P,$stale])['code'],'CONFLICT');foreach(['outdent','down','up']as$i=>$action){$d=call('PM','getProjectDetail',[P]);$cmd=['opId'=>str_repeat((string)($i+1),32),'action'=>$action,'taskIds'=>[T],'baseVersion'=>$d['structureVersion']];$r=write('PM','changeTaskStructure',[P,$cmd]);ok($r['ok'],json_encode($r));}ok(!ControlTower::hierarchy($s->rows('TASKS'),$s->rows('PROJECTS')));});
