test('recovery: committed read view, write fence, resume/rollback and conflict guards',function()use($s,$app){
    $token=token('PM');$tasks=$app->projectRows('TASKS',P);$old=$s->find('TASKS',T);$changed=$old;$changed['Parent_Task_ID']='DEMO-TSK-01-1-1';$changed['Sort_Order']='4096';$after=array_map(fn($t)=>$t['Task_ID']===T?$changed:$t,$tasks);
    $full=function($tasks)use($s){usort($tasks,fn($a,$b)=>strcmp($a['Task_ID'],$b['Task_ID']));return hash('sha256',Store::json(array_map(fn($t)=>array_map(fn($k)=>(string)($t[$k]??''),$s->columns('TASKS')),$tasks)));};
    $op='recovery-aaaaaaaa-aaaaaaaa-aaaaaaaa';$key='CR002_STRUCTURE_OP_'.hash('sha256',P.'|'.$op);$j=['opId'=>$op,'projectId'=>P,'actorId'=>'PM','status'=>'PREPARED','changes'=>[[T,$old['Parent_Task_ID'],$old['Sort_Order'],$changed['Parent_Task_ID'],$changed['Sort_Order']]],'beforeFullVersion'=>$full($tasks),'afterFullVersion'=>$full($after)];
    $s->put('TASKS',$changed);$s->config($key,Store::json($j));$s->config('CR002_STRUCTURE_ACTIVE',Store::json(['key'=>$key]));$s->config('DATABASE_SCHEMA_VERSION','MIGRATING');
    eq($s->find('TASKS',T)['Parent_Task_ID'],$old['Parent_Task_ID']);eq($app->call('getProjectDetail',[P],$token)['structurePending']['opId'],$op);denied(fn()=>$app->call('updateMyTask',[T,'20','In Progress','','UNIFIED_TASKS_V2'],$token),'RECOVERY');
    $r=$app->call('recoverTaskStructure',[P,$op,'ROLLBACK','UNIFIED_TASKS_V2'],$token);eq($r['status'],'ROLLED_BACK');eq($s->find('TASKS',T)['Parent_Task_ID'],$old['Parent_Task_ID']);eq($s->schemaVersion(),'UNIFIED_TASKS_V2');eq($s->activeStructure(),null);
    $j['status']='PREPARED';$s->config($key,Store::json($j));$r=$app->call('recoverTaskStructure',[P,$op,'RESUME','UNIFIED_TASKS_V2'],$token);eq($r['status'],'COMPLETED');eq($s->find('TASKS',T)['Parent_Task_ID'],$changed['Parent_Task_ID']);
});
test('passwords: GAS UTF-16 length rules apply to non-ASCII and emoji',function()use($app){eq(ControlTower::length('ếếế'),3);eq(ControlTower::length('😀😀😀😀'),8);$t=token('PIC');denied(fn()=>$app->call('changePassword',['test-only-passphrase','ếếế'],$t),'8–128');ok($app->call('changePassword',['test-only-passphrase','ếếếếếếếế'],$t)['ok']);ok($app->call('login',['pic-user','ếếếếếếếế'])['token']!=='');});

test('performance: request-local scope cache invalidates after authorization-changing writes',function()use($app,$s){$pm=$s->find('USERS','PM');$admin=$s->find('USERS','ADMIN');eq(count($app->visible($pm)),10);eq(count($app->visible($pm)),10);$app->archive($admin,P,true);eq(count($app->visible($pm)),9);$app->archive($admin,P,false);eq(count($app->visible($pm)),10);});
test('performance: opt-in aggregate tracing contains no tokens or data',function()use($app){$file=sys_get_temp_dir().'/pmo-trace-'.bin2hex(random_bytes(5));$old=ini_get('error_log');ini_set('error_log',$file);putenv('PERF_TRACE_ENABLED=TRUE');try{$t=token('PM');$app->call('getProjects',[],$t);$log=file_get_contents($file);ok(str_contains($log,'pmo_performance'));ok(str_contains($log,'getProjects'));ok(!str_contains($log,$t));ok(!str_contains($log,'test-only-passphrase'));ok(!str_contains($log,'[DEMO]'));}finally{putenv('PERF_TRACE_ENABLED');ini_set('error_log',$old);if(is_file($file))unlink($file);}});

